import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"What is wikijs-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1788117098000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-wikijs-mcp" tabindex="-1">What is wikijs-mcp? <a class="header-anchor" href="#what-is-wikijs-mcp" aria-label="Permalink to “What is wikijs-mcp?”">​</a></h1><p>Search, read and edit Wiki.js pages, and manage its assets, users, groups and comments</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Because a wiki is where the answers already are, and getting at them through a browser breaks the thread. This server puts the wiki in reach of the client you are already working in — and does the two things that turn out to matter most once you try it: finding text that the built-in search cannot see, and not quietly overwriting somebody else while you do.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><ul><li><strong>Wiki.js 3.x.</strong> Still alpha with no release date, and its GraphQL schema is being flattened to root-level operations. This targets 2.x; the documents live in <code>src/gql/</code> so a 3.0 adapter is a new module rather than a rewrite.</li><li><strong>Minting API keys.</strong> Wiki.js can do it over GraphQL and this server deliberately cannot: a model able to create a full-access key could grant itself administrative access outliving the session. Revoking and listing keys are here.</li><li><strong>Editing the navigation menu.</strong> Wiki.js replaces the whole tree in one mutation, and a partial answer from a model would silently delete the rest.</li></ul>`,6)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};